      <div class="rent-history-filters"><label>{{ $t('legacy.t_a7ff541f4978') }}<input v-model="historyMonth" type="month"></label><label>{{ $t('legacy.t_42c950a2ce7c') }}<input v-model.trim="tenantFilter" :placeholder="$t('legacy.t_76dc13e8d8c0')"></label><label>{{ $t('legacy.t_4ce0ee8cc0b2') }}<input v-model.trim="unitFilter" :placeholder="$t('legacy.t_0049e42d5032')"></label><button @click="clearHistoryFilters">{{ $t('legacy.t_bdc000aa0264') }}</button></div>
