<td class="rent-history-check-cell"><input v-model="selectedIds" type="checkbox" :value="row.id" :aria-label="$t('ui.selectItemAria', { name: row.transactionNo })" @click.stop></td>
              <td><strong>{{ row.transactionNo }}</strong><small>{{ $lt(paymentMethodLabel(row.paymentMethod)) }}</small></td>
              <td>{{ row.tenantName }}<small>{{ row.leaseNo }}</small></td>
