              <td><b>{{ row.currency || 'MYR' }} {{ money(row.amount) }}</b></td>
              <td>{{ displayDate(row.transactionDate) }}</td>
              <td><span class="proof-state" :class="{ missing: !row.proofDocumentId }">{{ row.proofDocumentId ? $t('legacy.t_f31f8cf4ca3d') : $t('legacy.t_ee32021ea7ce') }}</span></td>
              <td><span class="tag" :class="confirmationClass(row.confirmationStatus)">{{ $lt(confirmationLabel(row.confirmationStatus)) }}</span></td>
              <td><button class="finance-detail-button" :aria-label="$t('legacy.t_d2efce3bbc7d')" @click.stop="openActions(row)">{{ $t('legacy.t_faea8c1db9cc') }}</button></td>
            </tr>
            <tr v-if="!loading && !rows.length"><td colspan="10" class="admin-owner-empty">{{ $t('legacy.t_127791a5adcf') }}</td></tr>
          </tbody>
        </table>
      </div>
      <div class="pager"><span>{{ $t('legacy.t_3b6ef811b85a') }} {{ totalRows }} {{ $t('legacy.t_86761b63a7bd') }}</span><div class="admin-building-pager"><button :disabled="pageNumber <= 1" @click="goPage(pageNumber - 1)">&lt;</button><button v-for="n in visiblePages" :key="n" :class="{ active: n === pageNumber }" @click="goPage(n)">{{ n }}</button><button :disabled="pageNumber >= totalPages" @click="goPage(pageNumber + 1)">&gt;</button><select v-model.number="pageSize"><option :value="10">{{ $t('legacy.t_fc6da0e815a1') }}</option><option :value="20">{{ $t('legacy.t_93d673672fa5') }}</option><option :value="50">{{ $t('legacy.t_529930b886d2') }}</option></select></div></div>
    </div>

<dialog ref="batchReopenDialog" class="modal admin-finance-decision-dialog"><form method="dialog" @submit.prevent="submitBatchReopen"><div class="modal-head"><div><h3>{{ $t('legacy.t_920e42140bdb') }}</h3><small>{{ $t('legacy.t_2e852f833138') }} {{ selectedReopenIds.length }} {{ $t('legacy.t_a3e8d0b35125') }}</small></div><button type="button" class="icon-close" @click="closeBatchReopen">×</button></div><div class="finance-decision-body"><div class="finance-decision-warning"><strong>{{ $t('legacy.t_9d42644f9014') }}</strong><span>{{ $t('legacy.t_b8f53aa3aa07') }}</span></div><label>{{ $t('legacy.t_2fe161329598') }}<textarea v-model.trim="batchReopenNote" maxlength="500" required :placeholder="$t('legacy.t_a57feeed2005')"></textarea></label><p v-if="actionError" class="admin-property-error">{{ $lt(actionError) }}</p></div><menu><button type="button" @click="closeBatchReopen">{{ $t('legacy.t_4d0b4688c787') }}</button><button class="primary-btn reject" :disabled="batchBusy">{{ batchBusy ? $t('legacy.t_1cac8ac7f58f') : $t('ui.batchReturnCount', { count: selectedReopenIds.length }) }}</button></menu></form></dialog>

    <dialog ref="actionDialog" class="modal rent-history-action-dialog"><template v-if="selectedRow"><div class="modal-head"><div><h3>{{ $t('legacy.t_6f4fd71f31f0') }}</h3><small>{{ selectedRow.transactionNo }}</small></div><button type="button" class="icon-close" @click="closeActions">×</button></div><div class="rent-action-summary"><div><span>{{ $t('legacy.t_42c950a2ce7c') }}</span><b>{{ selectedRow.tenantName }}</b></div><div><span>{{ $t('legacy.t_7d72a964480f') }}</span><b>{{ selectedRow.projectName }} / {{ selectedRow.unitNo }}</b></div><div><span>{{ $t('legacy.t_53178a0b4360') }}</span><b>{{ selectedRow.currency || 'MYR' }} {{ money(selectedRow.amount) }}</b></div><div><span>{{ $t('legacy.t_5b2ade445584') }}</span><b>{{ $lt(confirmationLabel(selectedRow.confirmationStatus)) }}</b></div></div><FinanceAllocationNoteEditor :record="selectedRow" @saved="loadData" /><div class="rent-operation-grid"><button v-if="selectedRow.proofDocumentId" type="button" @click="openProofFromActions">{{ $t('legacy.t_028bddd5aef5') }}</button><button v-if="selectedRow.proofDocumentId" type="button" @click="downloadProof">{{ $t('legacy.t_65bd3d49f475') }}</button><button type="button" @click="chooseProofFromActions">{{ selectedRow.proofDocumentId ? $t('legacy.t_cb3f0ffa0d8a') : $t('legacy.t_f202b281d042') }}</button><button type="button" :disabled="receiptBusy" @click="downloadReceiptFromActions">{{ $t('legacy.t_3f584f4c386e') }}</button><a :href="documentUrl(selectedRow, 'invoice')" download @click="closeActions">{{ $t('legacy.t_c78fa9626abb') }}</a><button type="button" @click="goToTenancyFromActions">{{ $t('legacy.t_24b12362e45a') }}</button><button v-if="selectedRow.confirmationStatus === 'confirmed'" type="button" class="danger" @click="openReopenFromActions">{{ $t('legacy.t_2954008c3811') }}</button></div></template></dialog>

    <dialog ref="reopenDialog" class="modal admin-finance-decision-dialog"><form method="dialog" @submit.prevent="submitReopen"><div class="modal-head"><div><h3>{{ $t('finance.reopenTitle') }}</h3><small>{{ selectedRow?.transactionNo }}</small></div><button type="button" class="icon-close" @click="closeReopen">×</button></div><div class="finance-decision-body"><div class="finance-decision-warning"><strong>{{ $t('finance.reopen') }}</strong><span>{{ $t('legacy.t_1d66af6e42e1') }}</span></div><label>{{ $t('finance.reopenNote') }}<textarea v-model.trim="reopenNote" maxlength="500" required :placeholder="$t('finance.reopenNotePlaceholder')"></textarea></label><p v-if="actionError" class="admin-property-error">{{ $lt(actionError) }}</p></div><menu><button type="button" @click="closeReopen">{{ $t('legacy.t_4d0b4688c787') }}</button><button class="primary-btn reject" :disabled="reopenSaving">{{ reopenSaving ? $t('legacy.t_1e038f9b55ec') : $t('finance.reopen') }}</button></menu></form></dialog>

    <dialog ref="proofDialog" class="modal admin-finance-proof-dialog"><div class="modal-head"><div><h3>{{ $t('legacy.t_08ca85f55e3c') }}</h3><small>{{ selectedRow?.proofName || selectedRow?.transactionNo }}</small></div><button type="button" class="icon-close" @click="closeProof">×</button></div><div class="finance-proof-viewer"><div v-if="proofLoading" class="admin-owner-state">{{ $t('legacy.t_e526ed184e85') }}</div><img v-else-if="proofUrl && selectedRow?.proofMimeType?.startsWith('image/')" :src="proofUrl" :alt="$t('legacy.t_08ca85f55e3c')"><iframe v-else-if="proofUrl && selectedRow?.proofMimeType === 'application/pdf'" :src="proofUrl" :title="$t('legacy.t_b1c0f608af9c')"></iframe><div v-else class="admin-owner-state">{{ proofError || $t('legacy.t_410b7e2a33ff') }}</div></div><menu><button @click="closeProof">{{ $t('legacy.t_ddc05404b0d6') }}</button><button class="primary-btn" :disabled="!selectedRow?.proofDocumentId" @click="downloadProof">{{ $t('legacy.t_fb332e3c9ee6') }}</button></menu></dialog>
  </section>
</template>

<script>
import { batchReopenAdminFinanceReviews, downloadAdminFinanceDocuments, fetchAdminRentFinanceProjects, fetchAdminRentFinanceReviews, fetchAdminRentProof, getAdminFinanceDocumentUrl, reopenAdminFinanceReview, uploadAdminRentProof } from '../services/propertyApi';
import FinanceAllocationNoteEditor from './FinanceAllocationNoteEditor.vue';
import { formatDate } from '../utils/dateFormat';

export default {
  components: { FinanceAllocationNoteEditor },
  inject: ['page'],
  data() { return { rows: [], selectedId: null, selectedIds: [], pageNumber: 1, pageSize: 10, totalRows: 0, totalPages: 1, loading: false, errorMessage: '', requestSerial: 0, proofBusy: false, receiptBusy: false, batchBusy: false, historyMonth: '', tenantFilter: '', unitFilter: '', proofLoading: false, proofError: '', proofUrl: '', reopenNote: '', batchReopenNote: '', reopenSaving: false, actionError: '' }; },
  computed: {
    selectedRow() { return this.rows.find(row => row.id === this.selectedId) || null; },
    selectedReopenIds() { return this.rows.filter(row => this.selectedIds.includes(row.id) && row.confirmationStatus === 'confirmed').map(row => row.id); },
    allPageSelected() { return this.rows.length > 0 && this.rows.every(row => this.selectedIds.includes(row.id)); },
    visiblePages() { const start = Math.max(1, Math.min(this.pageNumber - 2, this.totalPages - 4)); return Array.from({ length: Math.min(5, this.totalPages) }, (_, i) => start + i); },
    refreshNonce() { return this.page.adminFinanceRefreshNonce; },
    proofUploadNonce() { return this.page.adminRentProofUploadNonce; }
  },
  watch: {
    'page.moduleSearch'() { this.resetLoad(); }, 'page.globalSearch'() { this.resetLoad(); }, 'page.projectFilter'() { this.resetLoad(); }, 'page.statusFilter'() { this.resetLoad(); }, 'page.dateStart'() { this.resetLoad(); }, 'page.dateEnd'() { this.resetLoad(); }, historyMonth() { this.resetLoad(); }, tenantFilter() { this.resetLoad(); }, unitFilter() { this.resetLoad(); },
    pageSize() { this.pageNumber = 1; this.selectedIds = []; this.loadData(); }, refreshNonce(value, previous) { if (value > previous) this.loadData(); }, proofUploadNonce(value, previous) { if (value > previous) this.chooseProof(); }, rows: { deep: true, handler(rows) { if (!rows.some(row => row.id === this.selectedId)) this.selectedId = null; this.selectedIds = this.selectedIds.filter(id => rows.some(row => row.id === id)); } }
  },
  mounted() { this.loadData(); }, beforeUnmount() { this.revokeProofUrl(); },
  methods: {
    async loadData() { const serial = ++this.requestSerial; const preferredId = this.selectedId; this.loading = true; this.errorMessage = ''; try { const [response, projects] = await Promise.all([fetchAdminRentFinanceReviews({ page: this.pageNumber, pageSize: this.pageSize, keyword: this.page.globalSearch || this.page.moduleSearch || '', projectName: String(this.page.projectFilter || '').includes('全部') ? '' : this.page.projectFilter, status: this.statusParam(this.page.statusFilter) || 'history', startDate: this.page.dateStart, endDate: this.page.dateEnd, billingMonth: this.historyMonth ? `${this.historyMonth}-01` : '', tenantName: this.tenantFilter, unitNo: this.unitFilter }), fetchAdminRentFinanceProjects()]); if (serial !== this.requestSerial) return; this.rows = response.rows || []; this.totalRows = response.page?.totalRows || 0; this.totalPages = response.page?.totalPages || 1; this.pageNumber = response.page?.page || 1; this.selectedId = this.rows.some(row => row.id === preferredId) ? preferredId : null; this.page.adminFinanceProjects = projects || []; this.page.adminFinanceMetrics = this.metrics(response.summary || {}); } catch (e) { if (serial !== this.requestSerial) return; this.rows = []; this.errorMessage = e.message || 'API request failed'; this.page.adminFinanceMetrics = null; } finally { if (serial === this.requestSerial) this.loading = false; } },
    metrics(s) { return [{ label: '租金收款記錄', value: `${Number(s.totalCount || 0)} 筆`, delta: `RM ${this.money(s.totalAmount)}`, trend: 'up' }, { label: '已上傳憑證', value: `${Number(s.withProofCount || 0)} 筆`, delta: '線下審批憑證', trend: 'up' }, { label: '缺少憑證', value: `${Number(s.missingProofCount || 0)} 筆`, delta: '需要補上文件', trend: Number(s.missingProofCount) ? 'down' : 'up' }, { label: '本月收款金額', value: `RM ${this.money(s.monthAmount)}`, delta: '按收款日期統計', trend: 'up' }]; },
    resetLoad() { this.pageNumber = 1; this.selectedIds = []; this.loadData(); }, clearHistoryFilters() { this.historyMonth = ''; this.tenantFilter = ''; this.unitFilter = ''; }, goPage(n) { if (n >= 1 && n <= this.totalPages && n !== this.pageNumber) { this.pageNumber = n; this.selectedIds = []; this.loadData(); } }, selectRow(row) { this.selectedId = row.id; }, togglePageSelection(event) { const ids = this.rows.map(row => row.id); this.selectedIds = event.target.checked ? [...ids] : []; }, documentUrl(row, type) { return row?.id ? getAdminFinanceDocumentUrl(row.id, type) : '#'; }, async batchDownload(type) { const ids = [...this.selectedIds]; if (!ids.length || this.batchBusy) return; this.batchBusy = true; try { const result = await downloadAdminFinanceDocuments(ids, type); this.saveBlob(result.blob, result.filename); this.page.showToast(this.$ltf`已生成 ${ids.length} 份${type === 'invoice' ? '发票' : '收据'}`); } catch (error) { this.page.showToast(error.message || '批量下载失败'); } finally { this.batchBusy = false; } },
    openBatchReopen() { if (!this.selectedReopenIds.length) return; this.batchReopenNote = ''; this.actionError = ''; this.$refs.batchReopenDialog?.showModal(); }, closeBatchReopen() { this.$refs.batchReopenDialog?.close(); }, async submitBatchReopen() { if (!this.batchReopenNote || !this.selectedReopenIds.length || this.batchBusy) return; const ids = [...this.selectedReopenIds]; this.batchBusy = true; this.actionError = ''; try { await batchReopenAdminFinanceReviews(ids, this.batchReopenNote); this.closeBatchReopen(); this.selectedIds = []; await this.loadData(); this.page.showToast(this.$ltf`已退回 ${ids.length} 笔租金收款，可重新确认`); } catch (error) { this.actionError = error.message || '批量退回失败'; } finally { this.batchBusy = false; } },
    openActions(row) { this.selectRow(row); this.$nextTick(() => this.$refs.actionDialog?.showModal()); }, closeActions() { this.$refs.actionDialog?.close(); },
    chooseProof() { if (!this.selectedRow || this.proofBusy) return; this.$refs.proofInput.value = ''; this.$refs.proofInput.click(); }, chooseProofFromActions() { this.closeActions(); this.chooseProof(); },
    openProofFromActions() { this.closeActions(); this.$nextTick(this.openProof); }, downloadReceiptFromActions() { this.closeActions(); this.downloadReceipt(); }, goToTenancyFromActions() { this.closeActions(); this.goToTenancy(); }, openReopenFromActions() { this.closeActions(); this.$nextTick(this.openReopen); },
    openReopen() { this.reopenNote = ''; this.actionError = ''; this.$refs.reopenDialog?.showModal(); }, closeReopen() { this.$refs.reopenDialog?.close(); }, async submitReopen() { if (!this.reopenNote) { this.actionError = this.$t('finance.reviewNoteRequired'); return; } this.reopenSaving = true; this.actionError = ''; try { await reopenAdminFinanceReview(this.selectedRow.id, this.reopenNote); this.closeReopen(); await this.loadData(); this.page.showToast('租金确认已撤销，可重新确认收款'); } catch (error) { this.actionError = error.message || this.$t('finance.reopenFailed'); } finally { this.reopenSaving = false; } },
    async uploadSelectedProof(event) { const file = event.target.files?.[0]; if (!file) return; if (!this.validProof(file)) { event.target.value = ''; return; } const replacing = Boolean(this.selectedRow.proofDocumentId); this.proofBusy = true; try { await uploadAdminRentProof(this.selectedRow.id, file); await this.loadData(); this.page.showToast(replacing ? '租金憑證已更換' : '租金憑證已補上'); } catch (e) { this.page.showToast(e.message || '租金憑證上傳失敗'); } finally { this.proofBusy = false; event.target.value = ''; } }, validProof(file) { if (!['application/pdf', 'image/jpeg', 'image/png'].includes(file.type) || file.size > 10 * 1024 * 1024) { this.page.showToast('只支援 10MB 以內的 PDF、JPG 或 PNG 憑證'); return false; } return true; },
     async openProof() { if (!this.selectedRow?.proofDocumentId) return; this.revokeProofUrl(); this.proofLoading = true; this.proofError = ''; this.$refs.proofDialog?.showModal(); try { const result = await fetchAdminRentProof(this.selectedRow.proofDocumentId); this.proofUrl = URL.createObjectURL(result.blob); } catch (e) { this.proofError = e.message || '租金付款憑證載入失敗'; } finally { this.proofLoading = false; } }, closeProof() { this.$refs.proofDialog?.close(); this.revokeProofUrl(); }, revokeProofUrl() { if (this.proofUrl) URL.revokeObjectURL(this.proofUrl); this.proofUrl = ''; }, async downloadProof() { try { const result = await fetchAdminRentProof(this.selectedRow.proofDocumentId, true); this.saveBlob(result.blob, this.selectedRow.proofName || `rent-proof-${this.selectedRow.id}`); } catch (e) { this.page.showToast(e.message || '租金付款憑證下載失敗'); } }, async downloadReceipt(row = this.selectedRow) { if (!row?.id || this.receiptBusy) return; this.receiptBusy = true; try { window.location.assign(getAdminFinanceDocumentUrl(row.id, 'receipt')); this.page.showToast('租金收據下載已開始'); } catch (e) { this.page.showToast(e.message || '租金收據下載失敗'); } finally { this.receiptBusy = false; } }, saveBlob(blob, fileName) { const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = fileName; link.style.display = 'none'; document.body.appendChild(link); link.click(); window.setTimeout(() => { link.remove(); URL.revokeObjectURL(url); }, 1000); },
    goToTenancy() { const keyword = this.selectedRow?.tenantName || this.selectedRow?.unitNo || ''; this.page.selectModule('adminTenants'); this.$nextTick(() => { this.page.globalSearch = keyword; }); }, statusParam(v) { return ({ '已確認': 'confirmed', '已退回': 'rejected' })[v] || ''; }, confirmationLabel(v) { return ({ confirmed: '已確認', rejected: '已退回' })[v] || '已完成'; }, confirmationClass(v) { return v === 'rejected' ? 'red' : 'green'; }, paymentMethodLabel(v) { return ({ bank_transfer: '銀行轉帳', online_transfer: '網上轉帳', cheque: '支票', cash: '現金', online_banking: '網上銀行' })[v] || v || '—'; }, displayDate(v) { return formatDate(v); }, monthLabel(v) { return v ? String(v).slice(0, 7) : '—'; }, money(v) { return Number(v || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
}
};
</script>

<style scoped>
.admin-rent-finance-workspace{display:block}.finance-review-list-panel{width:100%;min-width:0}.rent-history-batch-actions{display:flex;align-items:center;justify-content:flex-end;gap:8px;flex-wrap:wrap}.rent-history-batch-actions>span{color:#547083;font-size:12px;font-weight:700}.rent-history-batch-actions>button{min-height:34px;padding:0 12px;border:1px solid #91c9cd;border-radius:7px;background:#fff;color:#08717a;font-size:11px;font-weight:700;cursor:pointer}.rent-history-batch-actions>button:hover:not(:disabled){background:#eefafa}.rent-history-batch-actions>button.danger{border-color:#efb7b7;background:#fff6f5;color:#bf3636}.rent-history-batch-actions>button:disabled{cursor:not-allowed;opacity:.45}.rent-history-check-cell{width:38px;text-align:center}.rent-history-check-cell input{width:16px;height:16px;accent-color:#0b8f96;cursor:pointer}.rent-history-filters{display:flex;gap:10px;align-items:end;padding:12px 16px}.rent-history-filters label{display:grid;gap:4px;color:#52657a;font-size:12px}.rent-history-filters input{border:1px solid #cdd8e4;border-radius:6px;padding:8px 9px}.rent-history-filters>button{border:1px solid #cdd8e4;background:#fff;border-radius:6px;padding:8px 12px}.proof-state{display:inline-flex;align-items:center;min-height:26px;padding:0 9px;border-radius:999px;background:#eaf8ef;color:#168143;font-size:11px;font-weight:700}.proof-state.missing{background:#fff2df;color:#b96a00}.rent-history-action-dialog{width:min(680px,calc(100vw - 32px));padding:0;overflow:hidden}.rent-action-summary{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:20px}.rent-action-summary>div{display:grid;gap:5px;padding:12px;border:1px solid #e0e8f0;border-radius:9px;background:#f8fafc}.rent-action-summary span{color:#718096;font-size:11px}.rent-action-summary b{color:#173b5d;overflow-wrap:anywhere}.rent-operation-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;padding:0 20px 20px}.rent-operation-grid button,.rent-operation-grid a{display:flex;align-items:center;justify-content:center;min-height:40px;padding:0 14px;border:1px solid #c8d7e4;border-radius:8px;background:#fff;color:#174f7b;font-size:13px;font-weight:700;text-decoration:none;cursor:pointer}.rent-operation-grid button:hover,.rent-operation-grid a:hover{border-color:#68aeb3;background:#eff9f8;color:#087276}.rent-operation-grid .danger{grid-column:1/-1;border-color:#efb4b8;background:#fff4f4;color:#c7333e}.rent-history-action-dialog menu{display:flex;justify-content:flex-end;margin:0;padding:14px 20px;border-top:1px solid #e5ebf1;background:#f8fafc}.rent-history-action-dialog menu button{min-height:36px;padding:0 18px;border:1px solid #cad6e2;border-radius:7px;background:#fff}@media(max-width:700px){.panel-head{align-items:flex-start;flex-direction:column}.rent-history-batch-actions{justify-content:flex-start}.rent-history-filters{flex-wrap:wrap}.rent-action-summary,.rent-operation-grid{grid-template-columns:1fr}.rent-operation-grid .danger{grid-column:auto}}
</style>
